1	package cli
2	
3	import (
4		"context"
5		"crypto/rand"
6		"encoding/hex"
7		"errors"
8		"fmt"
9		"os"
10		"path/filepath"
11		"runtime"
12		"strings"
13		"time"
14	
15		"golang.org/x/mod/semver"
16	)
17	
18	// Remote install orchestration: resolve tag → fetch metadata → download +
19	// verify + extract → place under pkg/<name>/ → link into bin/ → write
20	// manifest. The bin/ link goes through the same InstallPluginFromPath used
21	// by local-dev installs, so conflict handling, atomic replace, and the
22	// Windows symlink fallbacks are shared, not duplicated.
23	
24	// maxTagFallbacks bounds how many tags we walk down when the newest tag has
25	// no published assets (tag pushed, release not finished).
26	const maxTagFallbacks = 3
27	
28	// RemoteInstallOptions configures InstallPluginFromRepo. It holds only genuine
29	// options — the repository and the expected name are required arguments,
30	// because a caller that omits either is making a decision, not accepting a
31	// default.
32	type RemoteInstallOptions struct {
33		// Pin, when non-empty, installs exactly this tag and marks the
34		// manifest pinned so upgrade skips it.
35		Pin string
36		// Force replaces an existing managed entry with the same name.
37		Force bool
38		// AllowUnverified permits installing a release that publishes no
39		// checksums.txt covering this platform. Off by default: downloading and
40		// executing an unauthenticated binary is the supply-chain risk the
41		// checksum path exists to remove, so it takes an explicit opt-in.
42		AllowUnverified bool
43	}
44	
45	// RemoteInstallResult is what a successful remote install produced.
46	type RemoteInstallResult struct {
47		Installed *InstalledPlugin
48		Manifest  *PluginManifest
49		Metadata  *PluginMetadata
50		// SkippedTags lists newer tags that were passed over for missing
51		// assets, newest first. Callers surface these as warnings.
52		SkippedTags []string
53		// ReplacedFrom is the repository a --force install displaced, set only
54		// when it differs from the one just installed. --force is *for* replacing,
55		// so this is not an error — but the confirmation for a URL install names a
56		// URL, never the plugin it is about to overwrite, and the remote picks that
57		// name. Surfacing it is what turns an uninformed replacement into an
58		// informed one, and gives the user the URL to put things back.
59		ReplacedFrom string
60	}
61	
62	// InstallPluginFromRepo installs a plugin from a git repository URL.
63	// Dependency resolution deliberately does not happen here — callers
64	// (the install command) plan and confirm dependency installs first.
65	// expectedName is the plugin name the caller has already committed to — the
66	// index entry the user asked for, the requirement being satisfied, or the
67	// plugin being upgraded. Pass "" only for a bare `install <url>`, where the
68	// repository legitimately names itself; installRepoAtTag explains why a
69	// mismatch is otherwise fatal.
70	//
71	// It is a required argument rather than an options field on purpose. As a
72	// field it could be silently omitted, and omitting it reopens a no-prompt
73	// name-substitution hole; as an argument, passing "" is a visible choice at
74	// the call site.
75	func InstallPluginFromRepo(ctx context.Context, repoURL, expectedName string, opts RemoteInstallOptions) (*RemoteInstallResult, error) {
76		repoURL = strings.TrimRight(repoURL, "/")
77	
78		var tags []string
79		if opts.Pin != "" {
80			tags = []string{opts.Pin}
81		} else {
82			var err error
83			tags, err = listRemoteSemverTags(ctx, repoURL)
84			if err != nil {
85				return nil, err
86			}
87			if len(tags) == 0 {
88				return nil, fmt.Errorf("%s has no stable semver tags; prereleases are skipped, so pass --pin <tag> to install one (or a non-semver tag)", redactURL(repoURL))
89			}
90			if len(tags) > maxTagFallbacks {
91				tags = tags[:maxTagFallbacks]
92			}
93		}
94	
95		var lastErr error
96		for i, tag := range tags {
97			res, err := installRepoAtTag(ctx, repoURL, expectedName, tag, opts)
98			if err == nil {
99				res.SkippedTags = tags[:i]
100				return res, nil
101			}
102			lastErr = err
103			if !errors.Is(err, errAssetNotFound) {
104				return nil, err
105			}
106		}
107		return nil, lastErr
108	}
109	
110	func installRepoAtTag(ctx context.Context, repoURL, expectedName, tag string, opts RemoteInstallOptions) (*RemoteInstallResult, error) {
111		meta, err := fetchPluginMetadataAtTag(ctx, repoURL, tag)
112		if err != nil {
113			return nil, err
114		}
115		// The installed name comes from the *remote* — entire-plugin.yml's name:,
116		// else the repo basename.
117		var name string
118		if meta != nil && meta.Name != "" {
119			name = meta.Name
120		} else if name, err = pluginNameFromRepoURL(repoURL); err != nil {
121			return nil, err
122		}
123	
124		// Reconcile it with what the caller asked for. Unchecked, the remote chose
125		// the name unilaterally, which broke three things:
126		//
127		//  - `install <index-name>` could install something else entirely: the
128		//    index entry says "safe", the repo declares "hijack", and the user gets
129		//    entire-hijack on PATH with no prompt (index installs never prompt).
130		//  - --force escalated across plugins: the already-installed check below
131		//    tests the *remote-declared* name, so reinstalling A let A's repo
132		//    declare name: B and replace an unrelated installed B.
133		//  - A dependency installed under a different name never satisfied the
134		//    requirement, so dependencySatisfied/doctor reported it missing forever
135		//    and every future parent install re-attempted it.
136		//
137		// Fatal rather than a warning: every caller that sets ExpectedName has
138		// already made a trust decision about *that* name, and silently honoring a
139		// different one voids it. A legitimate rename is a catalog or requirement
140		// to fix, and the message says so.
141		if expectedName != "" && name != expectedName {
142			return nil, fmt.Errorf(
143				"%s declares plugin name %q but %q was requested; refusing to install under a name that was not asked for (update the plugin index entry or the requirement if the plugin was renamed)",
144				redactURL(repoURL), name, expectedName)
145		}
146	
147		existing, err := FindInstalledPlugin(name)
148		if err != nil {
149			return nil, err
150		}
151		if existing != nil && !opts.Force {
152			return nil, fmt.Errorf("plugin %q already installed at %s; use --force to replace", name, existing.Path)
153		}
154		// Note a --force replace that changes where the plugin comes from. A repo
155		// move is legitimate (entire-sem → entire-graph), which is why this is not
156		// refused — but the caller should be able to tell the user what was
157		// displaced and from where.
158		var replacedFrom string
159		if existing != nil {
160			if prev, prevErr := LoadPluginManifest(name); prevErr == nil && prev != nil &&
161				normalizeRepoURL(prev.RepoURL) != normalizeRepoURL(repoURL) {
162				replacedFrom = prev.RepoURL
163			}
164		}
165	
166		staging, err := os.MkdirTemp("", "entire-plugin-fetch-")
167		if err != nil {
168			return nil, fmt.Errorf("create staging dir: %w", err)
169		}
170		defer os.RemoveAll(staging)
171	
172		asset, err := downloadPluginAsset(ctx, meta, repoURL, name, tag, staging, opts.AllowUnverified)
173		if err != nil {
174			return nil, err
175		}
176	
177		binBase := pluginBinaryName(name)
178		stagedBin := filepath.Join(staging, "extracted-"+binBase)
179		if err := extractPluginBinary(asset.Path, name, stagedBin); err != nil {
180			return nil, err
181		}
182	
183		pkgDir, err := EnsurePluginPkgDir(name)
184		if err != nil {
185			return nil, err
186		}
187		sweepOldBinaries(pkgDir)
188		pkgBin := filepath.Join(pkgDir, binBase)
189		if err := replaceBinary(stagedBin, pkgBin); err != nil {
190			return nil, fmt.Errorf("place plugin binary: %w", err)
191		}
192	
193		// Digest the binary we actually placed, not just the archive it came from.
194		// asset.SHA256 covers the downloaded asset, which is discarded with the
195		// staging dir — so it records provenance but can never detect later
196		// tampering. binDigest is what `plugin doctor` re-checks.
197		binDigest, err := fileSHA256(pkgBin)
198		if err != nil {
199			return nil, fmt.Errorf("hash installed plugin binary: %w", err)
200		}
201	
202		manifest := &PluginManifest{
203			Name:         name,
204			RepoURL:      repoURL,
205			Tag:          tag,
206			Asset:        asset.Asset,
207			SHA256:       asset.SHA256,
208			BinarySHA256: binDigest,
209			Unverified:   !asset.Verified,
210			Pinned:       opts.Pin != "",
211			InstalledAt:  time.Now().UTC(),
212		}
213		if meta != nil {
214			manifest.Requires = meta.Requires
215		}
216		// The manifest is written before the bin/ link, immediately after the
217		// binary swap. Ordering matters because replaceBinary has already mutated
218		// pkg/<name>/: until the manifest catches up, it records the *previous*
219		// tag and binary_sha256 while the new binary is on disk, and
220		// checkManagedBinaryIntegrity reads that as tampering — a permanent false
221		// alarm on a perfectly good install. Writing it here leaves only the local
222		// re-hash above in that window.
223		//
224		// If the bin/ link then fails, the manifest is still accurate and doctor
225		// reports the real problem ("has an install manifest but no entry in the
226		// managed bin dir") with a fix that works, instead of accusing the user of
227		// tampering.
228		if err := SavePluginManifest(manifest); err != nil {
229			return nil, err
230		}
231	
232		installed, err := InstallPluginFromPath(InstallPluginOptions{SourcePath: pkgBin, Force: true})
233		if err != nil {
234			return nil, err
235		}
236		return &RemoteInstallResult{Installed: installed, Manifest: manifest, Metadata: meta, ReplacedFrom: replacedFrom}, nil
237	}
238	
239	// UpgradeOutcome describes what UpgradeInstalledPlugin did.
240	type UpgradeOutcome struct {
241		Name string
242		// Pinned: skipped because the manifest is pinned.
243		Pinned bool
244		// UpToDate: already at the newest tag.
245		UpToDate bool
246		// FromTag/ToTag are set when an upgrade actually happened.
247		FromTag, ToTag string
248	}
249	
250	// UpgradeInstalledPlugin re-resolves the newest tag for a remote-installed
251	// plugin and reinstalls when it differs from the manifest's tag. Plugins
252	// without a manifest (local-dev symlinks) are not upgradable.
253	func UpgradeInstalledPlugin(ctx context.Context, name string) (*UpgradeOutcome, error) {
254		m, err := LoadPluginManifest(name)
255		if err != nil {
256			return nil, err
257		}
258		if m == nil {
259			return nil, fmt.Errorf("plugin %q has no install manifest (local-dev install?); reinstall it from its repository URL to make it upgradable", name)
260		}
261		if m.Pinned {
262			return &UpgradeOutcome{Name: name, Pinned: true}, nil
263		}
264		tags, err := listRemoteSemverTags(ctx, m.RepoURL)
265		if err != nil {
266			return nil, err
267		}
268		if len(tags) == 0 {
269			return nil, fmt.Errorf("%s has no stable semver tags; prereleases are skipped, so pass --pin <tag> to move to one", redactURL(m.RepoURL))
270		}
271		// Semver comparison, not string equality: "v0.2.0" and "0.2.0" are the
272		// same version, and a remote that re-tagged with the other spelling
273		// must not trigger a reinstall.
274		if semver.Compare(canonicalSemver(tags[0]), canonicalSemver(m.Tag)) <= 0 {
275			return &UpgradeOutcome{Name: name, UpToDate: true}, nil
276		}
277		// Inherit the install-time trust decision: a plugin the user knowingly
278		// installed unverified shouldn't start failing on upgrade, and one
279		// installed verified must not silently downgrade to unverified.
280		res, err := InstallPluginFromRepo(ctx, m.RepoURL, name, RemoteInstallOptions{
281			Force: true, AllowUnverified: m.Unverified,
282		})
283		if err != nil {
284			return nil, err
285		}
286		// The install may have fallen back past an asset-less newest tag and
287		// landed on the version already installed — that's up-to-date, not an
288		// upgrade line claiming X → X.
289		if semver.Compare(canonicalSemver(res.Manifest.Tag), canonicalSemver(m.Tag)) <= 0 {
290			return &UpgradeOutcome{Name: name, UpToDate: true}, nil
291		}
292		return &UpgradeOutcome{Name: name, FromTag: m.Tag, ToTag: res.Manifest.Tag}, nil
293	}
294	
295	// replaceBinary moves src over dest atomically. On Windows, a running
296	// executable can't be replaced (sharing violation) but it *can* be renamed:
297	// move the old binary aside to a .old-<rand> file and retry; leftovers are
298	// swept on the next install. os.Rename fails across filesystems (staging is
299	// in the system temp dir), so a copy fallback covers that case.
300	func replaceBinary(src, dest string) error {
301		err := os.Rename(src, dest)
302		if err == nil {
303			return nil
304		}
305		if runtime.GOOS == windowsGOOS {
306			if asideErr := os.Rename(dest, oldBinaryAsidePath(dest)); asideErr == nil {
307				if err = os.Rename(src, dest); err == nil {
308					return nil
309				}
310			}
311		}
312		// Cross-device rename: copy + fsync-free write, then remove src.
313		in, openErr := os.Open(src) //nolint:gosec // staging file we created
314		if openErr != nil {
315			return errors.Join(err, openErr)
316		}
317		defer in.Close()
318		if writeErr := writeExecutable(in, dest); writeErr != nil {
319			return errors.Join(err, writeErr)
320		}
321		_ = os.Remove(src)
322		return nil
323	}
324	
325	// oldBinaryAsidePath returns a unique .old- sibling path for the
326	// rename-aside trick. Random suffix so concurrent upgrades can't collide.
327	func oldBinaryAsidePath(dest string) string {
328		var b [4]byte
329		if _, err := rand.Read(b[:]); err != nil {
330			return dest + ".old-fallback"
331		}
332		return dest + ".old-" + hex.EncodeToString(b[:])
333	}
334	
335	// sweepOldBinaries best-effort removes .old-* leftovers from the Windows
336	// rename-aside fallback. Failures are ignored — the files are inert.
337	func sweepOldBinaries(pkgDir string) {
338		entries, err := os.ReadDir(pkgDir)
339		if err != nil {
340			return
341		}
342		for _, e := range entries {
343			if strings.Contains(e.Name(), ".old-") {
344				_ = os.Remove(filepath.Join(pkgDir, e.Name()))
345			}
346		}
347	}
348	
349	// RemoveManagedPlugin removes a plugin's bin entries and its pkg dir.
350	// The dependency guard lives in the command layer so --force can bypass it.
351	func RemoveManagedPlugin(name string) error {
352		if err := RemoveInstalledPlugin(name); err != nil {
353			return err
354		}
355		return RemovePluginPkg(name)
356	}
